#### File B3: `src/lib/services/community/utils/supabase-client.ts` (MODIFY)

**Add new function:**

```typescript
export async function insertNavEvent(event: {
  student_id: string;
  course_id: string;
  lo_id: string;
  lo_type: string;
  session_id: string;
  duration_ms: number | null;
  referrer_lo: string | null;
  engagement: string;
}): Promise<void> {
  if (PUBLIC_ANON_MODE === "TRUE" || typeof supabase === "undefined") return;

  const { error } = await supabase.from("nav_events").insert({
    ...event,
    ts: new Date().toISOString()
  });

  if (error) {
    log.error("insertNavEvent failed:", error);
  }
}
```

**Add query functions for Phase C:**

```typescript
/** Fetch recent nav events for a course (for dashboard analysis) */
export async function getNavEventsByCourse(
  courseId: string,
  since: Date
): Promise<NavEventRow[]> {
  if (PUBLIC_ANON_MODE === "TRUE" || typeof supabase === "undefined") return [];

  const { data, error } = await supabase
    .from("nav_events")
    .select("*")
    .eq("course_id", courseId)
    .gte("ts", since.toISOString())
    .order("ts", { ascending: false })
    .limit(5000);

  if (error) {
    log.error("getNavEventsByCourse failed:", error);
    return [];
  }
  return (data ?? []) as NavEventRow[];
}

/** Detect thrashing: A->B->A within threshold_ms */
export async function getThrashingEvents(
  courseId: string,
  thresholdMs: number = 3 * 60 * 1000
): Promise<NavEventRow[]> {
  // Client-side post-processing of nav events
  // Fetch recent events, then detect A->B->A patterns
  const events = await getNavEventsByCourse(courseId, new Date(Date.now() - 60 * 60 * 1000));
  // Grouping and pattern detection happens in the dashboard aggregation service
  return events;
}
```

Also add the `NavEventRow` type at the top of the file (or in types.svelte.ts):
